//! Real C++ SCIP import. The index was generated by pinned scip-clang v0.4.1
//! from the checked-in C++ fixture; definitions stay definitions and
//! references never become resolved calls.

use archmeld_core::scip::{import_scip, ScipConfig};
use archmeld_core::snapshot::{capture_snapshot, SnapshotInputs, SnapshotOptions};
use archmeld_core::store::Store;
use serde_json::json;
use std::fs;
use std::path::Path;

const PROJECT: &str = "project.scip.cpp";

#[test]
fn real_cpp_scip_index_imports_references_without_promoting_calls() {
    let fixture_root =
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../../adapters/languages/fixtures/c-cpp");
    let index_path =
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../../upstream-probes/scip/cpp.scip");
    if !fixture_root.is_dir() || !index_path.is_file() {
        eprintln!("real C++ SCIP fixture missing; skipping");
        return;
    }
    let index_bytes = fs::read(&index_path).expect("cpp.scip");
    let dir = tempfile::tempdir().unwrap();
    let mut store = Store::open(dir.path().join("state")).unwrap();
    store.ensure_project(PROJECT, "expedition").unwrap();
    let captured = capture_snapshot(
        &mut store,
        PROJECT,
        &fixture_root,
        &SnapshotInputs {
            build_config: json!({"variant": "scip-cpp-real"}),
            environment: json!({"os": "test"}),
        },
        &SnapshotOptions {
            include_untracked: true,
            ..SnapshotOptions::default()
        },
    )
    .unwrap();
    let config_digest = captured.snapshot["config_digest"]
        .as_str()
        .unwrap()
        .to_string();
    let report = import_scip(
        &mut store,
        &ScipConfig {
            project_id: PROJECT,
            snapshot_id: &captured.snapshot_id,
            config_digest: &config_digest,
            run_id: "run.scip.cpp.real",
            max_entities_per_batch: 500,
            max_relations_per_batch: 2000,
        },
        &captured.files,
        &index_bytes,
    )
    .expect("import C++ SCIP");
    eprintln!(
        "cpp scip report: documents={} entities={} relations={} external={} diagnostics={} omitted={} unresolved={} coverage={}",
        report.documents,
        report.entities,
        report.relations,
        report.external_entities,
        report.diagnostics,
        report.omitted_documents,
        report.unresolved,
        report.coverage,
    );
    assert!(report.documents >= 2, "circle.cpp and main.cpp must import");
    assert!(report.entities >= 5, "C++ declarations must become entities");
    assert!(report.relations >= 1, "C++ references must become relations");
    assert_eq!(report.omitted_documents, 0);
    let kinds = store
        .relation_kinds(PROJECT, &captured.snapshot_id)
        .unwrap();
    assert!(kinds.contains("references"));
    assert!(
        !kinds.contains("resolved_call"),
        "SCIP references must not be promoted to resolved calls"
    );
    assert!(store.integrity_check().unwrap().is_empty());
}
